        vm.deal(attacker, 10 ether);

        // Create a victim address
        victim = address(0x123);
        vm.label(victim, "Victim");

        // Give victim some tokens (1% of total supply)
        uint256 totalSupply = MARSINU(TARGET).totalSupply();
        uint256 victimAmount = totalSupply / 100;
        deal(TARGET, victim, victimAmount);
    }

