        console.log("Victim balance:", MARSINU(TARGET).balanceOf(simpleVictim));
        console.log("Contract balance:", MARSINU(TARGET).balanceOf(TARGET));
        console.log("Attacker balance:", MARSINU(TARGET).balanceOf(attacker));

